       min-height: 100vh;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top left, rgba(36, 87, 214, 0.18), transparent 32rem),
         linear-gradient(135deg, #f8fbff 0%, var(--bg) 52%, #eef3ff 100%);
       line-height: 1.5;
     }

     .skip-link {
       position: absolute;
       left: 1rem;
       top: 1rem;
       z-index: 10;
       transform: translateY(-150%);
       border-radius: 999px;
       background: var(--text);
       color: #ffffff;
       padding: 0.75rem 1rem;
       text-decoration: none;
     }

     .skip-link:focus {
       transform: translateY(0);
       outline: 3px solid #ffffff;
       outline-offset: 3px;
     }

     main {
       width: min(100% - 2rem, 860px);
       margin: 0 auto;
       padding: 4rem 0;
     }

     .quiz-card {
       overflow: hidden;
       border: 1px solid rgba(216, 222, 234, 0.8);
       border-radius: 2rem;
       background: rgba(255, 255, 255, 0.92);
       box-shadow: var(--shadow);
       backdrop-filter: blur(18px);
     }

     .hero {
       padding: clamp(1.5rem, 5vw, 3rem);
       background: linear-gradient(135deg, #15203a 0%, #254fbf 100%);
       color: #ffffff;
     }

     .eyebrow {
       margin: 0 0 0.75rem;
       font-size: 0.78rem;
       font-weight: 700;
       letter-spacing: 0.12em;
       text-transform: uppercase;
       color: #cfdafe;
     }

     h1 {
       max-width: 12ch;
       margin: 0;
       font-size: clamp(2.25rem, 8vw, 4.75rem);
       line-height: 0.95;
       letter-spacing: -0.06em;
     }

     .intro {
       max-width: 58ch;
       margin: 1.25rem 0 0;
       color: #e7ecff;
       font-size: 1.08rem;
     }

     form {
       padding: clamp(1.25rem, 5vw, 3rem);
     }

     .form-field {
       margin: 0 0 1.5rem;
       padding: clamp(1rem, 3vw, 1.4rem);
       border: 1px solid var(--border);
       border-radius: 1.25rem;
       background: var(--card);
     }

     fieldset {
       min-width: 0;
       margin: 0;
       padding: 0;
       border: 0;
     }

     legend {
       margin-bottom: 0.45rem;
       padding: 0;
       font-size: 1.12rem;
       font-weight: 800;
       color: var(--text);
     }

     .help-text {
       margin: 0 0 1rem;
       color: var(--muted);
     }

     .choices {
       display: grid;
       grid-template-columns: repeat(2, minmax(0, 1fr));
       gap: 0.8rem;
       margin-top: 1rem;
     }

     .choice {
       display: flex;
       align-items: flex-start;
       gap: 0.75rem;
       min-height: 3.25rem;
       border: 1px solid var(--border);
       border-radius: 1rem;
       padding: 0.95rem;
       background: #fbfcff;
       cursor: pointer;
       transition: border-color 160ms ease, background-color 160ms ease, transform 160ms ease;
     }

     .choice:hover {
       border-color: #9fb1dc;
       background: var(--primary-soft);
       transform: translateY(-1px);
     }

     input[type="checkbox"] {
       width: 1.25rem;
       height: 1.25rem;
       flex: 0 0 auto;
       margin: 0.1rem 0 0;
       accent-color: var(--primary);
       cursor: pointer;
     }

     .choice:has(input[type="checkbox"]:checked) {
       border-color: var(--primary);
       background: var(--primary-soft);
     }

     input[type="checkbox"]:focus-visible {
       outline: 3px solid var(--primary);
       outline-offset: 3px;
     }

     .actions {
       display: flex;
       align-items: center;
       gap: 1rem;
       flex-wrap: wrap;
       margin-top: 2rem;
     }

     button {
       border: 0;
       border-radius: 999px;
       background: var(--primary);
       color: #ffffff;
       padding: 0.9rem 1.35rem;
       font: inherit;
       font-weight: 800;
       cursor: pointer;
       box-shadow: 0 12px 24px rgba(36, 87, 214, 0.28);
     }

     button:hover {
       background: var(--primary-hover);
     }

     button:focus-visible {
       outline: 3px solid var(--text);
       outline-offset: 4px;
     }

     .result {
       min-height: 1.5rem;
       margin: 0;
       color: var(--success);
       font-weight: 700;
     }

     @media (max-width: 640px) {
       main {
         width: min(100% - 1rem, 860px);
         padding: 0.5rem 0;
       }

       .quiz-card {
         border-radius: 1.25rem;
       }

       .choices {
         grid-template-columns: 1fr;
       }
     }

     @media (forced-colors: active) {
       .quiz-card,
       .form-field,
       .choice,
       button {
         forced-color-adjust: none;
         border: 1px solid CanvasText;
       }

       body,
       .quiz-card,
       .form-field,
       .choice {
         background: Canvas;
         color: CanvasText;
       }

       .hero,
       button,
       .skip-link {
         background: ButtonFace;
         color: ButtonText;
       }
     }
   </style>
