 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>

   <main id="main-content">
     <section class="quiz-card" aria-labelledby="quiz-title">
       <div class="hero">
         <p class="eyebrow">Multi-select quiz</p>
         <h1 id="quiz-title">Computer Languages</h1>
         <p class="intro">Choose every answer that applies. Some questions have more than one correct answer.</p>
       </div>

       <form id="quiz-form">
         <div class="form-field">
           <fieldset aria-describedby="q1-help">
             <legend>1. Which of these are programming languages?</legend>
             <p class="help-text" id="q1-help">Select all languages used to write software.</p>
             <div class="choices">
               <label class="choice" for="q1-python">
                 <input id="q1-python" name="q1" type="checkbox" value="python" data-correct="true">
                 Python
               </label>
               <label class="choice" for="q1-html">
                 <input id="q1-html" name="q1" type="checkbox" value="html">
                 HTML
               </label>
               <label class="choice" for="q1-ruby">
                 <input id="q1-ruby" name="q1" type="checkbox" value="ruby" data-correct="true">
                 Ruby
               </label>
               <label class="choice" for="q1-css">
                 <input id="q1-css" name="q1" type="checkbox" value="css">
                 CSS
               </label>
             </div>
           </fieldset>
         </div>

         <div class="form-field">
           <fieldset>
             <legend>2. Which languages commonly run in web browsers?</legend>
             <div class="choices">
               <label class="choice" for="q2-javascript">
                 <input id="q2-javascript" name="q2" type="checkbox" value="javascript" data-correct="true">
                 JavaScript
               </label>
               <label class="choice" for="q2-typescript">
                 <input id="q2-typescript" name="q2" type="checkbox" value="typescript" data-correct="true">
                 TypeScript
               </label>
               <label class="choice" for="q2-sql">
                 <input id="q2-sql" name="q2" type="checkbox" value="sql">
                 SQL
               </label>
               <label class="choice" for="q2-cobol">
                 <input id="q2-cobol" name="q2" type="checkbox" value="cobol">
                 COBOL
               </label>
             </div>
           </fieldset>
         </div>

         <div class="form-field">
           <fieldset>
             <legend>3. Which languages are often used for data analysis?</legend>
             <div class="choices">
               <label class="choice" for="q3-python">
                 <input id="q3-python" name="q3" type="checkbox" value="python" data-correct="true">
                 Python
               </label>
               <label class="choice" for="q3-r">
                 <input id="q3-r" name="q3" type="checkbox" value="r" data-correct="true">
                 R
               </label>
               <label class="choice" for="q3-swift">
                 <input id="q3-swift" name="q3" type="checkbox" value="swift">
                 Swift
               </label>
               <label class="choice" for="q3-kotlin">
                 <input id="q3-kotlin" name="q3" type="checkbox" value="kotlin">
                 Kotlin
               </label>
             </div>
           </fieldset>
         </div>

         <div class="actions">
           <button type="submit">Check answers</button>
           <p class="result" id="quiz-result" aria-live="polite"></p>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector("#quiz-form");
     const result = document.querySelector("#quiz-result");
     const questionNames = ["q1", "q2", "q3"];

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const score = questionNames.reduce((total, name) => {
         const answers = [...form.elements[name]];
         const isCorrect = answers.every((answer) => answer.checked === (answer.dataset.correct === "true"));
         return total + (isCorrect ? 1 : 0);
       }, 0);

       result.textContent = `You scored ${score} out of ${questionNames.length}.`;
     });
   </script>
 </body>
